/**
 * Delete ad-hoc matchUps modal with selective filtering.
 * Removes matchUps based on completion status (empty, unscored, completed).
 */
import { mutationRequest } from 'services/mutation/mutationRequest';
import { tournamentEngine } from 'services/factory/engine';
import { hasFinalResult } from 'functions/hasFinalResult';
import { renderForm } from 'courthive-components';
import { openModal } from './baseModal/baseModal';
import { isFunction } from 'functions/typeOf';
import { t } from 'i18n';

import { DELETE_ADHOC_MATCHUPS } from 'constants/mutationConstants';

type DeleteAdHocMatchUpsParams = {
  drawId?: string;
  roundNumber?: number;
  structure?: any;
  structureId?: string;
  callback?: (params: any) => void;
};

export function deleteAdHocMatchUps({
  drawId,
  roundNumber,
  structure,
  structureId,
  callback,
}: DeleteAdHocMatchUpsParams = {}): void {
  structureId = structureId || structure?.structureId;
  if (!structureId) return;

  const matchUps =
    tournamentEngine.allDrawMatchUps({
      matchUpFilters: { structureIds: [structureId] },
      drawId,
    }).matchUps || [];
  const roundNumbers = matchUps.reduce((roundNumbers: number[], matchUp: any) => {
    const roundNumber = matchUp.roundNumber;
    if (roundNumber && !roundNumbers.includes(roundNumber)) roundNumbers.push(roundNumber);
    return roundNumbers;
  }, []);

  roundNumber = roundNumber || (roundNumbers.length && roundNumbers[roundNumbers.length - 1]);
  if (!roundNumber) return;

  let inputs: any;

  const deleteRound = () => {
    const matchUpIds = matchUps
      .filter((matchUp: any) => {
        if (matchUp.roundNumber !== roundNumber) return;
        // A completed tie (COMPLETED, no winner) is completed, not unscored
        if (hasFinalResult(matchUp) && inputs.completed.checked) return true;
        if (
          matchUp.sides.some(({ participantId }: any) => participantId) &&
          !hasFinalResult(matchUp) &&
          inputs.unscored.checked
        )
          return true;
        return matchUp.sides.every(({ participantId }: any) => !participantId) && inputs.empties.checked;
      })
      .map(({ matchUpId }: any) => matchUpId);

    const methods = [
      {
        params: {
          removeCompleted: inputs.completed.checked,
          removeIncomplete: inputs.unscored.checked,
          removeUnassigned: inputs.empties.checked,
          structureId,
          matchUpIds,
          drawId,
        },
        method: DELETE_ADHOC_MATCHUPS,
      },
    ];

    const postMutation = (result: any) => {
      if (result.success) {
        if (isFunction(callback) && callback) callback({ refresh: true });
      } else {
        console.log({ postMutationError: result.error });
      }
    };

    if (matchUpIds.length) {
      mutationRequest({ methods, callback: postMutation });
    }
  };

  const buttons = [
    { label: t('common.cancel'), intent: 'none', close: true },
    { label: t('common.delete'), intent: 'is-danger', close: true, onClick: deleteRound },
  ];

  const roundNumberOptions = roundNumbers.map((rn) => ({ label: rn, value: rn }));

  const roundNumberSelection = {
    text: t('modals.deleteMatches.roundNumber'),
    fieldPair: {
      options: roundNumberOptions,
      field: 'roundNumber',
      value: roundNumber,
      id: 'roundNumber',
    },
  };
  const options = [
    roundNumberSelection,
    { spacer: true },
    {
      label: t('modals.deleteMatches.removeEmpty'),
      intent: 'is-success',
      checkbox: true,
      field: 'empties',
      checked: true,
      id: 'empties',
    },
    {
      label: t('modals.deleteMatches.removeIncomplete'),
      intent: 'is-danger',
      field: 'unscored',
      checkbox: true,
      id: 'unscored',
    },
    {
      label: t('modals.deleteMatches.removeCompleted'),
      intent: 'is-danger',
      field: 'completed',
      id: 'completed',
      checkbox: true,
      color: 'var(--tmx-accent-red, #ff6b6b)',
    },
  ];

  const content = (elem: HTMLElement) => (inputs = renderForm(elem, options));

  openModal({ title: t('modals.deleteMatches.title'), content, buttons });
}
